package retry

// Do calls fn until it succeeds or ctx is done, sleeping between attempts
// with exponential backoff capped at maxDelay so a flapping dependency is
// not hammered.
func Do(ctx context.Context, maxDelay time.Duration, fn func() error) error {
	delay := 10 * time.Millisecond
	for {
		err := fn()
		if err == nil {
			return nil
		}
		if !sleep(ctx, delay) {
			return ctx.Err()
		}
		delay = min(2*delay, maxDelay)
	}
}

export function chunk<T>(items: T[], size: number): T[][] {
  // Pages are cut from the front so callers that stream results can
  // render the first page early.
  const pages: T[][] = [];
  for (let start = 0; start < items.length; start += size) {
    pages.push(items.slice(start, start + size));
  }
  return pages;
}

