const Polynomial = struct { quad: f64, linear: f64, constant: f64 };

fn bezierPolynomial(start: f64, control: f64, end: f64) Polynomial {
    return .{
        .quad = start - 2 * control + end,
        .linear = 2 * (control - start),
        .constant = start,
    };
}

fn evaluate(curve: Polynomial, param: f64) f64 {
    return (curve.quad * param + curve.linear) * param + curve.constant;
}

fn addCut(cuts: *[10]f64, count: *usize, param: f64) void {
    if (param <= 1e-10 or param >= 1 - 1e-10 or !std.math.isFinite(param)) return;
    for (cuts[0..count.*]) |prior| {
        if (@abs(prior - param) < 1e-10) return;
    }
    if (count.* < cuts.len) {
        cuts[count.*] = param;
        count.* += 1;
    }
