    const quad = polynomial.quad;
    const linear = polynomial.linear;
    const constant = polynomial.constant - target;
    if (@abs(quad) < 1e-12) {
        if (@abs(linear) > 1e-12) addCut(cuts, count, -constant / linear);
        return;
