    return std::any_of(items.begin(), items.end(), [&](auto item) {
        return mesh.edges[item.edge].h1 < 0;
    });
}
int repair_assignments(
    Mesh &mesh,
    const std::vector<std::vector<Incident>> &incident,
    std::vector<std::string> &warnings
