    std::vector<int> unknown;
    for (size_t idx = 0; idx < mesh.edges.size(); ++idx) {
        if (mesh.edges[idx].h1 >= 0 && mesh.edges[idx].assignment == '?') {
            unknown.push_back(static_cast<int>(idx));
        }
    }
    if (unknown.empty()) return 0;
    if (unknown.size() > 24) {
        warnings.push_back("assignment repair skipped: more than 24 unknown creases");
        return 0;
    }
    int visited = 0;
    bool cutoff = false;
    auto feasible = [&]() {
        for (const auto &items : incident) {
            if (items.empty() || is_boundary(mesh, items)) continue;
            int difference = 0, remaining = 0;
            for (const auto &item : items) {
                char kind = mesh.edges[item.edge].assignment;
                if (kind == 'M') ++difference;
                else if (kind == 'V') --difference;
                else ++remaining;
            }
            bool possible = false;
            for (int target : {-2, 2}) {
                int delta = target - difference;
                if (std::abs(delta) <= remaining && (remaining - delta) % 2 == 0) {
                    possible = true;
                }
            }
            if (!possible) return false;
        }
        return true;
    };
    std::function<bool(size_t)> search = [&](size_t depth) {
        if (++visited > 200000) {
            cutoff = true;
            return false;
        }
        if (!feasible()) return false;
        if (depth == unknown.size()) return true;
        for (char assignment : {'M', 'V'}) {
            mesh.edges[unknown[depth]].assignment = assignment;
            if (search(depth + 1)) return true;
        }
        mesh.edges[unknown[depth]].assignment = '?';
        return false;
    };
    if (!search(0)) {
        for (int edge : unknown) mesh.edges[edge].assignment = '?';
        const char *msg = cutoff
            ? "assignment search budget exhausted"
            : "no assignment satisfies all interior Maekawa constraints";
        warnings.push_back(msg);
        return 0;
    }
    return static_cast<int>(unknown.size());
}
}
Diagnostics check_mesh(Mesh &mesh, bool repair) {
    Diagnostics diag;
    diag.warnings = mesh.warnings;
    auto incident = incidence(mesh);
    if (repair) diag.repaired = repair_assignments(mesh, incident, diag.warnings);
    for (size_t idx = 0; idx < mesh.vertices.size(); ++idx) {
        const auto &items = incident[idx];
        VertexCheck check;
        check.id = mesh.vertices[idx].id;
        check.degree = static_cast<int>(items.size());
        check.boundary = is_boundary(mesh, items);
        for (const auto &entry : items) {
            char kind = mesh.edges[entry.edge].assignment;
            if (mesh.edges[entry.edge].h1 < 0) continue;
            if (kind == 'M') ++check.mountains;
            else if (kind == 'V') ++check.valleys;
            else ++check.unknown;
        }
        if (!check.boundary && !items.empty()) {
            double sums[2] = {0, 0};
            for (size_t step = 0; step < items.size(); ++step) {
                double next = items[(step + 1) % items.size()].angle;
                double angle = next - items[step].angle;
                if (angle <= 0) angle += 2 * pi;
                sums[step % 2] += angle;
            }
            check.alternating_error = std::abs(sums[0] - pi);
            check.kawasaki = items.size() % 2 == 0
                && std::abs(sums[0] - pi) < 1e-6
                && std::abs(sums[1] - pi) < 1e-6;
            check.maekawa = check.unknown == 0
                && std::abs(check.mountains - check.valleys) == 2;
            const std::string label = "vertex " + std::to_string(check.id);
            if (!check.kawasaki) {
                diag.warnings.push_back(label + " fails Kawasaki");
            }
            if (!check.maekawa) {
                diag.warnings.push_back(label + " fails or cannot establish Maekawa");
            }
        }
        diag.checks.push_back(check);
    }
    return diag;
}
}

