        auto vert_b = by_id.find(crease.b);
        if (vert_a == by_id.end() || vert_b == by_id.end()) {
            mesh.warnings.push_back("crease refers to unknown vertex");
            continue;
        }
        Key edge_key = key(vert_a->second, vert_b->second);
        auto found_edge = edge_map.find(edge_key);
        if (found_edge == edge_map.end()) {
            mesh.warnings.push_back("crease is not a face edge");
            continue;
        }
        if (!assigned.insert(edge_key).second) {
            mesh.warnings.push_back("duplicate crease ignored");
            continue;
        }
        Edge &item = mesh.edges[found_edge->second];
        if (item.h1 < 0) {
            mesh.warnings.push_back("boundary edge cannot be a fold crease");
            continue;
        }
        item.assignment = crease.assignment;
        item.weight = crease.weight;
    }
    return mesh;
}
}

