  if (cue.kind === 'follow') return `${cue.fixture} -> ${cue.dancer}`;
  return Object.keys(cue.from).join(', ');
}

export function cueSheet(stage: Stage, issues: Issue[], warnings: string[]): string {
  const counts = `Dancers: ${stage.dancers.size}, fixtures: ${stage.fixtures.size}`;
