  for (const cue of stage.cues) {
    const range = `${cue.start.toFixed(2)}-${cue.end.toFixed(2)} beats`;
    const startSeconds = beatToSeconds(cue.start, stage.tempos).toFixed(2);
    lines.push(`${range} | ${startSeconds} s | ${cue.kind} | ${cueLabel(cue)}`);
  }
  for (const warning of warnings) lines.push(`WARNING: ${warning}`);
  for (const issue of issues) {
