private fun adjusted(leg: Leg, weather: Weather): Segment? {
    val flight = leg.mode != Mode.GROUND
    if (flight && leg.from in weather.closed) return null
    val targetClosed = flight && leg.to in weather.closed
    val target = if (targetClosed) leg.diversion ?: return null else leg.to
    if (flight && target in weather.closed) return null
