    val diversionDelay = if (targetClosed) leg.diversionMinutes else 0L
    val departure = leg.departure.plusSeconds(delay * 60)
    val arrival = leg.arrival.plusSeconds((delay + diversionDelay) * 60)
    return Segment(leg, target, departure, arrival, targetClosed)
}

