                        slurOpen = true
                    }
                    if note.slurEnd {
                        if !slurOpen { diagnostics.append(Diagnostic(severity: "warning", location: location, message: "slur end has no start")) }
                        slurOpen = false
                    }
                case .rest(let rest):
                    if let t = rest.tuplet { tupletCounts["\(t.written):\(t.played)", default: 0] += 1 }
                case .slurStart:
                    if slurOpen { diagnostics.append(Diagnostic(severity: "warning", location: location, message: "nested slur start")) }
                    slurOpen = true
                case .slurEnd:
                    if !slurOpen { diagnostics.append(Diagnostic(severity: "warning", location: location, message: "slur end has no start")) }
                    slurOpen = false
                case .dynamic: break
                }
            }
            for (key, count) in tupletCounts {
                let first = key.split(separator: ":").first.flatMap { Int($0) } ?? 0
                if first > 0 && count % first != 0 {
                    diagnostics.append(Diagnostic(severity: "warning", location: location, message: "incomplete tuplet \(key)") )
                }
            }
        }
        if slurOpen { diagnostics.append(Diagnostic(severity: "warning", location: "voice \(voice.name)", message: "unclosed slur")) }
    }
    return diagnostics
